import os
import glob

def stream_files(path):
    os.chmod(path, 0o600)
    os.chown(path, os.getuid(), os.getuid())

    with open(path, 'rb') as f:
        yield from f

def get_files(path):
    return glob.glob(os.path.join(path, '*'))

files = get_files('/var/www/documents')
for file in files:
    if os.path.isfile(file):
        for chunk in stream_files(file):
            print(chunk)

