from collections import namedtuple

SubscriptionInfo = namedtuple('SubscriptionInfo', ['user_id', 'collection', 'frequency', 'start_time'])

class SubscriptionsDb():
    def __init__(self):
        self._conn = sqlite3.connect(DATABASE_PATH)

    def add_subscription(self, info: SubscriptionInfo):
        query = "INSERT INTO subscriptions VALUES (? , ?, ?, ?)"

       _conn.execute(query, info)
       _conn.commit()

    def get_subscriptions_for_user(self, user_id):
        query = "SELECT * FROM subscriptions WHERE user_id = :user_id"
        cursor = _conn.execute(query, {'user_id': user_id})
        return cursor.fetchall()

    def get_subscriptions_for_collection(self, collection):
        query = "SELECT * FROM subscriptions WHERE collection = :collection"
        cursor = _conn.execute(query, {'collection': collection})
        return cursor.fetchall()

    def remove_subscription(self, info: SubscriptionInfo):
        query = "DELETE FROM subscriptions WHERE user_id = ? AND collection = ? AND frequency = ? AND start_time = ?"

        _conn.execute(query, info)
        _conn.commit()

 tqdm
from typing import List, Dict

def process_cities(cities: List[Dict[str, any]]) -> Dict[str, int]:
    city_counts = {}
    for city in tqdm(cities, desc="Processing cities"):
        city_id = city['id']
        city_counts[city_id] = cities.count(city)

        if city_counts[city_id] > 1000:
            city_counts[city_id] = 1000

    return city_counts

