import os
from datetime import datetime
from jinja2 import Template

def render_template(template_dir, template_file, context={}):
    with open(os.path.join(template_dir, template_file)) as f:
        template = Template(f.read(), autoescape=True)
    return template.render(context)

def render_error(template_dir, error_template, message, timestamp):
    return render_template(template_dir, error_template, {
        'message': message,
        'timestamp': timestamp
    })

