import requests
import time

def get_stocks():
    url = 'http://api.example.com/stocks'
    response = requests.get(url)

    data = response.json()
    stocks = data['stocks']

    return stocks

def get_price(symbol):
    url = 'http://api.example.com/price?symbol=' + symbol
    response = requests.get(url)

    data = response.json()

    return data['price']

def buy(symbol, quantity):
    url = 'http://api.example.com/buy'
    response = requests.post(url, data={
        'symbol': symbol,
        'quantity': quantity
    })

    return response.json()

def sell(symbol, quantity):
    url = 'http://api.example.com/sell'
    response = requests.post(url, data={
        'symbol': symbol,
        'quantity': quantity
    })

    return response.json()

def trade(stocks):
    stock = stocks[0]

    price = get_price(stock['symbol'])
    if price > stock['price'] + 1:
        sell(stock['symbol'], stock['quantity'])
        print('Sold %d shares of %s at $%s' % (stock['quantity'],
                                                stock['symbol'],
                                                price))

    if price < stock['price'] - 1:
        buy(stock['symbol'], stock['quantity'])
        print('Bought %d shares of %s at $%s' % (stock['quantity'],
                                                  stock['symbol'],
                                                  price))

stocks = get_stocks()

while True:
    trade(stocks)

    time.sleep(60)

