from jinja2 import Template

def render_chart(title, data):
    chart_html = """
    <h1>{{ title }}</h1>
    <ul>
        {% for item in data %}
            <li>{{ item[0]}}: {{ item[1] }}</li>
        {% endfor %}
    </ul>
    """

    template = Template(chart_html, autoescape=True)
    return template.render(title=title, data=data)

