import re

email = re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b')
domain_pattern = re.compile(r'@\w+\.\w')

def extract_domain(email):
    if email.match(email):
        return domain_pattern.search(email).group(0)
    else:
        return None

